{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For the end-of-quarter inventory of 150 units per product, should this be treated as an exact requirement (inventory must equal exactly 150) or as a minimum (inventory must be at least 150)?"
  ],
  "rationale": "The response asks for a single policy choice between two mutually exclusive constraint types (exact vs. minimum) for the same inventory variable."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "The contract reservations table lists a number of units per product per quarter — should these be treated as minimum delivery requirements (you must deliver at least this many units in that quarter, with any extra production carried as inventory), or as exact delivery targets (you must deliver exactly this many units in that quarter)?"
  ],
  "rationale": "The response asks for a single policy choice between two mutually exclusive interpretations of the contract reservations, which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 2,
  "is_atomic": false,
  "atomic_questions": [
    "Should the delay compensation be charged on the shortfall (required minus delivered) for each quarter",
    "does that shortfall persist into the next quarter (i.e., you must make up the delayed units later, and you pay compensation for each quarter the units remain undelivered)"
  ],
  "rationale": "The response asks two distinct policy questions: first, whether compensation is calculated on the quarterly shortfall, and second, whether that shortfall carries over to subsequent quarters with ongoing compensation."
}

